51	/// Unique suffix source for batch staging directories, shared across datasets.
52	static BATCH_COUNTER: AtomicU64 = AtomicU64::new(0);
53	
54	/// Per-dataset locks: readers (GET/list) take a shared guard, writers
55	/// (single PUT and batch PUT) an exclusive one, so a concurrent request can
56	/// only ever observe the dataset before or after a complete batch.
57	static DATASET_LOCKS: std::sync::LazyLock<
58	    RwLock<std::collections::HashMap<String, Arc<RwLock<()>>>>,
59	> = std::sync::LazyLock::new(|| RwLock::new(std::collections::HashMap::new()));
60	
61	async fn dataset_lock(name: &str) -> Arc<RwLock<()>> {
62	    {
63	        let locks = DATASET_LOCKS.read().await;
64	        if let Some(lock) = locks.get(name) {
65	            return lock.clone();
66	        }
67	    }
68	    let mut locks = DATASET_LOCKS.write().await;
69	    locks
70	        .entry(name.to_owned())
71	        .or_insert_with(|| Arc::new(RwLock::new(())))
72	        .clone()
73	}
