89	async fn put_record(
90	    State(state): State<AppState>,
91	    PathParam((name, key)): PathParam<(String, String)>,
92	    body: Bytes,
93	) -> Response {
94	    if !valid_identifier(&name) || !valid_identifier(&key) {
95	        return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
96	    }
97	    if body.is_empty() {
98	        return error_response(StatusCode::BAD_REQUEST, "invalid_json");
99	    }
100	    let value: Value = match serde_json::from_slice(&body) {
101	        Ok(v) => v,
102	        Err(_) => return error_response(StatusCode::BAD_REQUEST, "invalid_json"),
103	    };
104	
105	    // Serialize against any batch in progress on this dataset; single
106	    // writers serialize with each other on the same lock as well.
107	    let lock = dataset_lock(&name).await;
108	    let _guard = lock.write().await;
109	    if let Err(resp) = write_file_atomic(&state, &name, &key, &body).await {
110	        return resp;
111	    }
112	    Json(json!({ "key": key, "value": value })).into_response()
113	}
