235	/// Key-only filter for record listing, parsed from the query string.
236	/// Either a prefix match, or a lower/upper bound range (each bound
237	/// inclusive or exclusive), but never both.
238	#[derive(Default)]
239	struct KeyFilter {
240	    prefix: Option<String>,
241	    /// (bound, inclusive)
242	    lower: Option<(String, bool)>,
243	    /// (bound, inclusive)
244	    upper: Option<(String, bool)>,
245	}
246	
247	impl KeyFilter {
248	    fn matches(&self, key: &str) -> bool {
249	        if let Some(prefix) = &self.prefix {
250	            return key.starts_with(prefix.as_str());
251	        }
252	        if let Some((bound, inclusive)) = &self.lower {
253	            let ok = if *inclusive {
254	                key >= bound.as_str()
255	            } else {
256	                key > bound.as_str()
257	            };
258	            if !ok {
259	                return false;
260	            }
261	        }
262	        if let Some((bound, inclusive)) = &self.upper {
263	            let ok = if *inclusive {
264	                key <= bound.as_str()
265	            } else {
266	                key < bound.as_str()
267	            };
268	            if !ok {
269	                return false;
270	            }
271	        }
272	        true
273	    }
274	}
