285	/// Decode one query-string component: `%XX` escapes and `+` as space.
286	fn percent_decode(s: &str) -> Result<String, ()> {
287	    let bytes = s.as_bytes();
288	    let mut out = Vec::with_capacity(bytes.len());
289	    let mut i = 0;
290	    while i < bytes.len() {
291	        match bytes[i] {
292	            b'%' => {
293	                if i + 2 >= bytes.len() {
294	                    return Err(());
295	                }
296	                let hi = hex_val(bytes[i + 1]).ok_or(())?;
297	                let lo = hex_val(bytes[i + 2]).ok_or(())?;
298	                out.push(hi << 4 | lo);
299	                i += 3;
300	            }
301	            b'+' => {
302	                out.push(b' ');
303	                i += 1;
304	            }
305	            b => {
306	                out.push(b);
307	                i += 1;
308	            }
309	        }
310	    }
311	    String::from_utf8(out).map_err(|_| ())
312	}
