541	/// Set a file's mtime and fsync it off the async runtime's worker threads
542	/// (set_modified/fsync are blocking syscalls).
543	async fn stamp_mtime_durable(path: PathBuf, at: SystemTime) -> std::io::Result<()> {
544	    tokio::task::spawn_blocking(move || {
545	        let file = std::fs::File::open(&path)?;
546	        file.set_modified(at)?;
547	        file.sync_all()
548	    })
549	    .await
550	    .map_err(std::io::Error::other)??;
551	    Ok(())
552	}
