563	/// One batch key as recorded in MANIFEST.
564	#[derive(serde::Serialize, serde::Deserialize)]
565	struct ManifestKey {
566	    key: String,
567	    /// Whether the record existed (and was snapshotted into `old/`) before
568	    /// the batch.
569	    existed: bool,
570	}
571	
572	/// On-disk MANIFEST describing a staged batch.
573	#[derive(serde::Serialize, serde::Deserialize)]
574	struct Manifest {
575	    name: String,
576	    commit_at_ms: u128,
577	    keys: Vec<ManifestKey>,
578	}
579	
580	impl Manifest {
581	    fn commit_time(&self) -> SystemTime {
582	        SystemTime::UNIX_EPOCH + std::time::Duration::from_millis(self.commit_at_ms as u64)
583	    }
584	}
585	
586	/// A staged batch ready to be switched into place.
587	struct StagedBatch {
588	    dir: PathBuf,
589	    manifest: Manifest,
590	}
591	
592	fn now_epoch_ms() -> u128 {
593	    SystemTime::now()
594	        .duration_since(SystemTime::UNIX_EPOCH)
595	        .map(|d| d.as_millis())
596	        .unwrap_or(0)
597	}
598	
599	/// Snapshot existing records and stage every new payload, write MANIFEST and
600	/// then the durable COMMIT marker. No dataset record is modified until this
601	/// returns. On error the staging directory is removed; the dataset is left
602	/// untouched.
603	async fn stage_batch(
604	    state: &AppState,
605	    name: &str,
606	    entries: &[(String, Value)],
607	) -> std::io::Result<StagedBatch> {
608	    let dir = staging_dir(state, name);
609	    let new_dir = dir.join("new");
610	    let old_dir = dir.join("old");
611	    let setup = async {
612	        tokio::fs::create_dir_all(&new_dir).await?;
613	        tokio::fs::create_dir_all(&old_dir).await?;
614	        // Make the staging directory itself durable.
615	        fsync_dir(state.data_dir.as_ref()).await?;
616	        Ok::<(), std::io::Error>(())
617	    }
618	    .await;
619	    if let Err(e) = setup {
620	        let _ = tokio::fs::remove_dir_all(&dir).await;
621	        return Err(e);
622	    }
623	
624	    let result = async {
625	        let mut manifest_keys = Vec::with_capacity(entries.len());
626	        for (key, value) in entries {
627	            // Snapshot the pre-request file, if any. A hardlink keeps the
628	            // exact inode (content and mtime) alive for rollback.
629	            let target = record_path(state, name, key);
630	            let snapshot = old_dir.join(format!("{key}.json"));
631	            let existed = match tokio::fs::hard_link(&target, &snapshot).await {
632	                Ok(()) => true,
633	                Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
634	                Err(e) => return Err(e),
635	            };
636	            manifest_keys.push(ManifestKey {
637	                key: key.clone(),
638	                existed,
639	            });
640	
641	            let body = serde_json::to_vec(value).map_err(std::io::Error::other)?;
642	            write_file_atomic_in(&new_dir, &new_dir.join(format!("{key}.json")), &body).await?;
643	        }
644	        // Persist the snapshot hardlinks' directory entries; recovery may
645	        // need them to undo a committed batch.
646	        fsync_dir(&old_dir).await?;
647	
648	        // The manifest (with the batch's commit timestamp) must be durable
649	        // before COMMIT: recovery relies on it to resume or undo the batch.
650	        let manifest = Manifest {
651	            name: name.to_owned(),
652	            commit_at_ms: now_epoch_ms(),
653	            keys: manifest_keys,
654	        };
655	        let manifest_body = serde_json::to_vec_pretty(&manifest).map_err(std::io::Error::other)?;
656	        write_file_atomic_in(&dir, &dir.join(MANIFEST_FILE), &manifest_body).await?;
657	
658	        // Commit point: once this rename + fsync is durable, the batch must
659	        // either apply fully on every future startup or be explicitly
660	        // aborted.
661	        write_file_atomic_in(&dir, &dir.join(COMMIT_MARKER), b"committed\n").await?;
662	        Ok::<Manifest, std::io::Error>(manifest)
663	    }
664	    .await;
665	
666	    match result {
667	        Ok(manifest) => Ok(StagedBatch { dir, manifest }),
668	        Err(e) => {
669	            let _ = tokio::fs::remove_dir_all(&dir).await;
670	            Err(e)
671	        }
672	    }
673	}
674	
675	/// Rename every staged payload into the dataset, stamp each record's mtime
676	/// with the batch commit time (updatedAt is the write-completion moment),
677	/// fsync, then read each record back and verify the stored value. Returns
678	/// the verified `(key, value, modified)` rows.
679	async fn switch_batch(
680	    state: &AppState,
681	    name: &str,
682	    staged: &StagedBatch,
683	    entries: &[(String, Value)],
684	) -> std::io::Result<Vec<(String, Value, SystemTime)>> {
685	    let dir = ensure_dataset_dir_raw(state, name).await?;
686	    let new_dir = staged.dir.join("new");
687	    let commit_time = staged.manifest.commit_time();
688	
689	    for item in &staged.manifest.keys {
690	        let from = new_dir.join(format!("{}.json", item.key));
691	        let to = record_path(state, name, &item.key);
692	        // rename(2) atomically replaces the destination on Unix.
693	        tokio::fs::rename(&from, &to).await?;
694	    }
695	    // One fsync after all renames makes the whole switch durable together.
696	    fsync_dir(&dir).await?;
697	    // The dataset directory may itself be new; persist its parent entry too.
698	    fsync_dir(state.data_dir.as_ref()).await?;
699	
700	    let expected: HashMap<&str, &Value> = entries.iter().map(|(k, v)| (k.as_str(), v)).collect();
701	    let mut verified = Vec::with_capacity(staged.manifest.keys.len());
702	    for item in &staged.manifest.keys {
703	        let key = item.key.as_str();
704	        let path = record_path(state, name, key);
705	
706	        // Rename preserves the staged file's mtime; stamp it with the batch
707	        // commit time so updatedAt reflects the write completion.
708	        stamp_mtime_durable(path.clone(), commit_time).await?;
709	
710	        let bytes = tokio::fs::read(&path).await?;
711	        let modified = tokio::fs::metadata(&path).await?.modified()?;
712	        let stored: Value = serde_json::from_slice(&bytes).map_err(std::io::Error::other)?;
713	        if Some(&stored) != expected.get(key).copied() {
714	            return Err(std::io::Error::other(format!(
715	                "post-commit verification mismatch for {name}/{key}"
716	            )));
717	        }
718	        verified.push((item.key.clone(), stored, modified));
719	    }
720	    Ok(verified)
721	}
722	
723	async fn ensure_dataset_dir_raw(state: &AppState, name: &str) -> std::io::Result<PathBuf> {
724	    let dir = state.data_dir.join(name);
725	    tokio::fs::create_dir_all(&dir).await?;
726	    Ok(dir)
727	}
728	
729	/// Durably abandon a staged batch: mark ABORT, restore every snapshot and
730	/// delete newly created records, fsync the dataset, then discard the
731	/// journal. Idempotent, so it can be re-driven by crash recovery.
732	async fn abort_batch(state: &AppState, name: &str, staged: &StagedBatch) -> std::io::Result<()> {
733	    // The ABORT marker makes the rollback decision durable before any
734	    // dataset file is touched.
735	    let abort_path = staged.dir.join(ABORT_MARKER);
736	    if tokio::fs::try_exists(&abort_path).await.unwrap_or(false) {
737	        // Already decided; nothing to write.
738	    } else {
739	        write_file_atomic_in(&staged.dir, &abort_path, b"aborted\n").await?;
740	    }
741	
742	    let old_dir = staged.dir.join("old");
743	    let mut first_err: Option<std::io::Error> = None;
744	    for item in &staged.manifest.keys {
745	        let target = record_path(state, name, &item.key);
746	        if item.existed {
747	            let snapshot = old_dir.join(format!("{}.json", item.key));
748	            // Restore the old inode (content + mtime). A missing snapshot
749	            // means a previous attempt already restored it.
750	            match tokio::fs::rename(&snapshot, &target).await {
751	                Ok(()) => {}
752	                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
753	                Err(e) if first_err.is_none() => first_err = Some(e),
754	                Err(_) => {}
755	            }
756	        } else {
757	            // Newly created by the batch; remove it. NotFound means an
758	            // earlier attempt already removed it.
759	            match tokio::fs::remove_file(&target).await {
760	                Ok(()) => {}
761	                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
762	                Err(e) if first_err.is_none() => first_err = Some(e),
763	                Err(_) => {}
764	            }
765	        }
766	    }
767	    if let Err(e) = fsync_dir(&state.data_dir.join(name)).await
768	        && first_err.is_none()
769	    {
770	        first_err = Some(e);
771	    }
772	    if let Err(e) = fsync_dir(state.data_dir.as_ref()).await
773	        && first_err.is_none()
774	    {
775	        first_err = Some(e);
776	    }
777	
778	    finish_batch_cleanup(&staged.dir, &abort_path).await;
779	
780	    match first_err {
781	        Some(e) => Err(e),
782	        None => Ok(()),
783	    }
784	}
785	
786	/// Retire the journal markers durably, then remove the staging directory.
787	/// Shared by the commit and abort paths.
788	async fn finish_batch_cleanup(staging: &Path, abort_path: &Path) {
789	    let _ = tokio::fs::remove_file(staging.join(COMMIT_MARKER)).await;
790	    let _ = tokio::fs::remove_file(abort_path).await;
791	    let _ = tokio::fs::remove_file(staging.join(MANIFEST_FILE)).await;
792	    let _ = fsync_dir(staging).await;
793	    let _ = tokio::fs::remove_dir_all(staging).await;
794	}
795	
796	/// Remove the journal of a successfully applied batch. Errors here are not
797	/// fatal to the request (the batch is already durable); startup recovery
798	/// sweeps anything left behind.
799	async fn discard_batch(staged: &StagedBatch) {
800	    finish_batch_cleanup(&staged.dir, &staged.dir.join(ABORT_MARKER)).await;
801	}
802	
803	async fn put_records(
804	    State(state): State<AppState>,
805	    PathParam(name): PathParam<String>,
806	    body: Bytes,
807	) -> Response {
808	    if !valid_identifier(&name) {
809	        return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
810	    }
811	    let entries = match parse_batch_records(&body) {
812	        Ok(entries) => entries,
813	        Err(BatchError::InvalidIdentifier) => {
814	            return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
815	        }
816	        Err(BatchError::InvalidJson) => {
817	            return error_response(StatusCode::BAD_REQUEST, "invalid_json");
818	        }
819	    };
820	
821	    // An empty batch is a legal no-op: 200 with an empty records array.
822	    if entries.is_empty() {
823	        return Json(json!({ "name": name, "records": [] })).into_response();
824	    }
825	
826	    // Exclusive with every other read and write of this dataset for the
827	    // duration of the commit.
828	    let lock = dataset_lock(&name).await;
829	    let _guard = lock.write().await;
830	
831	    let staged = match stage_batch(&state, &name, &entries).await {
832	        Ok(staged) => staged,
833	        Err(e) => {
834	            tracing_error(&e);
835	            return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
836	        }
837	    };
838	
839	    let verified = match switch_batch(&state, &name, &staged, &entries).await {
840	        Ok(rows) => rows,
841	        Err(e) => {
842	            tracing_error(&e);
843	            // Restore the exact pre-request dataset; if even that fails the
844	            // on-disk journal is re-driven (towards abort) at next startup.
845	            if let Err(rollback_err) = abort_batch(&state, &name, &staged).await {
846	                tracing_error(&rollback_err);
847	            }
848	            return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
849	        }
850	    };
851	
852	    discard_batch(&staged).await;
853	
854	    // Byte-wise order on UTF-8 is Unicode code-point order.
855	    let mut verified = verified;
856	    verified.sort_by(|a, b| a.0.cmp(&b.0));
857	    let records: Vec<Value> = verified
858	        .into_iter()
859	        .map(|(key, value, modified)| {
860	            json!({
861	                "key": key,
862	                "value": value,
863	                "updatedAt": format_rfc3339_utc(modified),
864	            })
865	        })
866	        .collect();
867	    Json(json!({ "name": name, "records": records })).into_response()
868	}
869	
870	/// Finish or undo one staging directory found at startup. MANIFEST drives
871	/// every decision, so resume work is idempotent no matter how far a prior
872	/// attempt (live or recovery) got.
873	async fn recover_one_batch(data_dir: &Path, staging: &Path) {
874	    let file_name = match staging.file_name().and_then(|n| n.to_str()) {
875	        Some(n) => n.to_owned(),
876	        None => {
877	            let _ = tokio::fs::remove_dir_all(staging).await;
878	            return;
879	        }
880	    };
881	    // Layout: .<name>.batch-<pid>-<n>, identifiers are [A-Za-z0-9_-].
882	    let marked = file_name.strip_prefix('.').unwrap_or(&file_name);
883	    let Some((_dir_name, _)) = marked.split_once(".batch-") else {
884	        let _ = tokio::fs::remove_dir_all(staging).await;
885	        return;
886	    };
887	
888	    // Crashed before/while writing MANIFEST or COMMIT: no record was ever
889	    // renamed, so the dataset is untouched and the journal can be discarded.
890	    let manifest_path = staging.join(MANIFEST_FILE);
891	    let commit_path = staging.join(COMMIT_MARKER);
892	    let abort_path = staging.join(ABORT_MARKER);
893	    let has_manifest = tokio::fs::try_exists(&manifest_path).await.unwrap_or(false);
894	    let has_commit = tokio::fs::try_exists(&commit_path).await.unwrap_or(false);
895	    if !has_manifest || !has_commit {
896	        let _ = tokio::fs::remove_dir_all(staging).await;
897	        return;
898	    }
899	
900	    let manifest_bytes = match tokio::fs::read(&manifest_path).await {
901	        Ok(b) => b,
902	        // A torn manifest means the batch never reached its commit point;
903	        // the dataset was not modified.
904	        Err(_) => {
905	            let _ = tokio::fs::remove_dir_all(staging).await;
906	            return;
907	        }
908	    };
909	    let manifest: Manifest = match serde_json::from_slice(&manifest_bytes) {
910	        Ok(m) => m,
911	        Err(_) => {
912	            let _ = tokio::fs::remove_dir_all(staging).await;
913	            return;
914	        }
915	    };
916	    let name = manifest.name.clone();
917	    let dataset_dir = data_dir.join(&name);
918	    let has_abort = tokio::fs::try_exists(&abort_path).await.unwrap_or(false);
919	    let new_dir = staging.join("new");
920	    let old_dir = staging.join("old");
921	
922	    if has_abort {
923	        // Resume an interrupted rollback.
924	        let _ = tokio::fs::create_dir_all(&dataset_dir).await;
925	        for item in &manifest.keys {
926	            let target = dataset_dir.join(format!("{}.json", item.key));
927	            if item.existed {
928	                let snapshot = old_dir.join(format!("{}.json", item.key));
929	                // Missing snapshot: already restored in an earlier pass.
930	                let _ = tokio::fs::rename(&snapshot, &target).await;
931	            } else {
932	                let _ = tokio::fs::remove_file(&target).await;
933	            }
934	        }
935	        let _ = fsync_dir(&dataset_dir).await;
936	        let _ = fsync_dir(data_dir).await;
937	    } else {
938	        // Resume an interrupted commit. Both moves and the mtime stamping
939	        // are re-applied, so an already-finished switch is a no-op.
940	        if let Err(e) = tokio::fs::create_dir_all(&dataset_dir).await {
941	            eprintln!("recovery: cannot create dataset {name}: {e}");
942	            return;
943	        }
944	        let commit_time = manifest.commit_time();
945	        for item in &manifest.keys {
946	            let target = dataset_dir.join(format!("{}.json", item.key));
947	            let staged_new = new_dir.join(format!("{}.json", item.key));
948	            // Missing staged file: already moved in an earlier pass.
949	            if let Err(e) = tokio::fs::rename(&staged_new, &target).await
950	                && e.kind() != std::io::ErrorKind::NotFound
951	            {
952	                eprintln!("recovery: cannot apply {}/{}: {e}", name, item.key);
953	            }
954	            // Restore the durable commit mtime whether this pass moved the
955	            // file or an earlier one did.
956	            if let Ok(file) = std::fs::File::open(&target) {
957	                let _ = file.set_modified(commit_time);
958	                let _ = file.sync_all();
959	            }
960	        }
961	        let _ = fsync_dir(&dataset_dir).await;
962	        let _ = fsync_dir(data_dir).await;
963	    }
964	
965	    // The dataset is now in a complete state; retire the journal.
966	    finish_batch_cleanup(staging, &abort_path).await;
967	}
968	
969	/// Sweep staging directories left by processes that died mid-batch. Runs
970	/// once before the server starts accepting requests.
971	async fn recover_pending_batches(state: &AppState) {
972	    let mut entries = match tokio::fs::read_dir(state.data_dir.as_ref()).await {
973	        Ok(entries) => entries,
974	        // A fresh deployment has no data directory yet.
975	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return,
976	        Err(e) => {
977	            eprintln!("recovery: cannot scan data dir: {e}");
978	            return;
979	        }
980	    };
981	    loop {
982	        let entry = match entries.next_entry().await {
983	            Ok(Some(entry)) => entry,
984	            Ok(None) => break,
985	            Err(e) => {
986	                eprintln!("recovery: cannot enumerate data dir: {e}");
987	                break;
988	            }
989	        };
990	        let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
991	            continue;
992	        };
993	        if file_name.starts_with('.') && file_name.contains(".batch-") {
994	            recover_one_batch(state.data_dir.as_ref(), &entry.path()).await;
995	        }
996	    }
997	}
998	
999	#[tokio::main]
1000	async fn main() -> Result<(), Box<dyn Error>> {
1001	    let bind = env::var("VDE_BIND").unwrap_or_else(|_| "127.0.0.1:8080".to_owned());
1002	    let data_dir = env::var("VDE_DATA_DIR")
1003	        .map(PathBuf::from)
1004	        .unwrap_or_else(|_| PathBuf::from("./data"));
1005	    let state = AppState {
1006	        data_dir: Arc::new(data_dir),
1007	    };
1008	
1009	    // Finish or undo any batch left in flight by a previous process before
1010	    // serving traffic.
1011	    recover_pending_batches(&state).await;
1012	
1013	    let listener = tokio::net::TcpListener::bind(&bind).await?;
1014	    let app = Router::new()
1015	        .route("/health", get(health))
1016	        .route("/version", get(version))
1017	        .route(
1018	            "/datasets/{name}/records/{key}",
1019	            put(put_record).get(get_record),
1020	        )
1021	        .route(
1022	            "/datasets/{name}/records",
1023	            get(list_records).put(put_records),
1024	        )
1025	        .with_state(state);
1026	
1027	    println!("Listening on http://{}", listener.local_addr()?);
1028	    axum::serve(listener, app)
1029	        .with_graceful_shutdown(async {
1030	            let _ = tokio::signal::ctrl_c().await;
1031	        })
1032	        .await?;
1033	    Ok(())
1034	}
