    if let Some((bound, _)) = &cursor.filter.lower {
        if !valid_identifier(bound) {
            return Err(());
        }
    }
    if let Some((bound, _)) = &cursor.filter.upper {
        if !valid_identifier(bound) {
            return Err(());
        }
    }
    if let Some(prefix) = &cursor.filter.prefix {
        if !valid_identifier(prefix) {
            return Err(());
        }
    }
    Ok(cursor)
}

